-- PASSO 1: backups reversíveis do estado atual (Fábrica, setores PRODUTOS + CÂMARA FRIA)
drop table if exists public.bkp_reset_setores_fabrica_20260603_estoque;
drop table if exists public.bkp_reset_setores_fabrica_20260603_estoque_lotes;
drop table if exists public.bkp_reset_setores_fabrica_20260603_etiquetas;

create table public.bkp_reset_setores_fabrica_20260603_estoque as
  select * from estoque
  where loja_id=1 and produto_master_id in (
    select id from produtos_master where setor in ('PRODUTOS','produtos','CÂMARA FRIA','Câmara Fria'));

create table public.bkp_reset_setores_fabrica_20260603_estoque_lotes as
  select * from estoque_lotes
  where loja_id=1 and produto_id in (
    select id from produtos_master where setor in ('PRODUTOS','produtos','CÂMARA FRIA','Câmara Fria'));

create table public.bkp_reset_setores_fabrica_20260603_etiquetas as
  select * from etiquetas_qr
  where loja_atual_id=1 and status='recebida' and produto_master_id in (
    select id from produtos_master where setor in ('PRODUTOS','produtos','CÂMARA FRIA','Câmara Fria'));

select
  (select count(*) from public.bkp_reset_setores_fabrica_20260603_estoque)       as bkp_estoque,
  (select count(*) from public.bkp_reset_setores_fabrica_20260603_estoque_lotes)  as bkp_estoque_lotes,
  (select count(*) from public.bkp_reset_setores_fabrica_20260603_etiquetas)      as bkp_etiquetas;
